define(['ojs/ojcore', 'knockout', 'ojs/ojselectcombobox', 'ojs/ojprogress', 'ojs/ojnavigationlist', 'ojs/ojswitcher', 'ojs/ojchart',
        'ojs/ojtable', 'ojs/ojrowexpander', 'ojs/ojknockouttemplateutils', 'ojs/ojarraytreedataprovider', 'ojs/ojflattenedtreedataproviderview',
        'ojs/ojarraydataprovider', 'ojs/ojtrain'],
    function (oj, ko) {
            function pageViewModel(params) {
                var self = this;

                // Parseaza valorile din URL (optionale)...
                var params      = new URLSearchParams(window.location.search);
                self.judet      = params.has('judet')      ? ko.observable(         params.get('judet')      ) : ko.observable();
                self.institutie = params.has('institutie') ? ko.observable(parseInt(params.get('institutie'))) : ko.observable();
                self.an         = params.has('an')         ? ko.observable(parseInt(params.get('an'))        ) : ko.observable();
                self.tabCurent  = params.has('tab')        ? ko.observable(         params.get('tab')        ) : ko.observable('cheltuieli');

                // Cronologie bugete...
                self.afiseazaCronologie        = ko.observable(false);
                self.pasiCronologie            = ko.observableArray([]);
                self.pasCronologie             = ko.observable('pas5');

                // Drop-down-uri...
                self.judete                    = ko.observableArray()
                self.institutii                = ko.observableArray();
                self.ani                       = ko.observableArray();

                // Widgeturi...
                self.progressValue             = ko.observable(-1);
                
                self.cheltuieliBarTitle        = ko.observable();
                self.cheltuieliBarSeries       = ko.observableArray();
                self.cheltuieliBarGroups       = ko.observableArray();

                self.venituriBarTitle          = ko.observable();
                self.venituriBarSeries         = ko.observableArray();
                self.venituriBarGroups         = ko.observableArray();

                self.cheltuieliPieTitle        = ko.observable();
                self.cheltuieliPieDataProvider = ko.observable();
                self.cheltuieliTableDataSource = ko.observable();

                self.venituriPieTitle          = ko.observable();
                self.venituriPieDataProvider   = ko.observable();
                self.venituriTableDataSource   = ko.observable();
                self.dateTableDataProvider     = ko.observable();
                self.uatTableDataProvider      = ko.observable();

                /*
                 * Descarca judete...
                 */
                 $.getJSON('json/judete.json')
                     .done(function(data) {
                         // Ani (incarca intii)...
                         var ani = [];
                         for (var i = 2026, n = 2016; i >= n; i--) {
                             ani.push({ "label": i, "value": i });
                         }
                         self.ani(ani);

                         // Judete...
                         self.judete(
                             $.map(data, function(item) {
                                 return { "label": item.nume, "value": item.cod };
                             })
                         );
                 });
                
                /*
                 * Judete (drop-down handler)...
                 */
                self.judetSchimba = function(event, data) {
                    if (event.detail.value) {
                        // Indicator incarcare...
                        self.progressValue(-1);

                        // Descarca 'json/AN/JUDET/institutii.json'...
                        $.getJSON(['json', self.an(), self.judet(), 'institutii.json'].join('/'))
                            .done(function(data) {
                                self.institutii(
                                    $.map(data, function(institutie) {
                                        return { "label": institutie.nume, "value": institutie.cif };
                                    })
                                );
                            })
                            .fail(function() {
                                self.institutie('');
                                self.institutii([]);
                            })
                            .always(function() {
                                // Opreste indicatorul incarcare...
                                self.progressValue(0);
                            });
                    }
                };

                /*
                 * Institutii (drop-down handler)...
                 */
                self.institutieSchimba = function(event, data) {
                    if (event.detail.value && event.detail.value !== event.detail.previousValue) {
                        // Descarca + afiseaza executie bugetara a unei institutii...
                        descarcaExecutieBugetara(self, self.judet(), self.institutie(), self.an());
                    }
                };

                /*
                 * Ani (drop-down handler)...
                 */
                self.aniSchimba = function(event, data) {
                    if (event.detail.value 
                        && (event.detail.value !== event.detail.previousValue || event.detail.updatedFrom === "external")) {
                        // Afiseaza calendar adoptare bugete locale...
                        populeazaDateCronologie(self, self.an());

                        // Descarca + afiseaza executie bugetara a unei institutii...
                        descarcaExecutieBugetara(self, self.judet(), self.institutie(), self.an());
                    }
                }

                /*
                 * Tab...
                 */
                self.tabCurent.subscribe(function(newValue) {
                   schimbaParametriiInURL(self);
                });

                /*
                 * Populeaza date footer
                 */
                 populeazaDateFooter(self);
            }

            /**
             * Descarca datele pentru o anume institutie pentru un anume an.
             * @param self
             * @param judet
             * @param institutie (cif)
             * @param an
             */
            function descarcaExecutieBugetara(self, judet, institutie, an) {
                if (judet && an) {
                    // Indicator incarcare...
                    self.progressValue(-1);
                    
                    // Descarca 'json/AN/JUDET/INSTITUTIE.json'...
                    $.getJSON(['json', self.an(), self.judet(), self.institutie() + '.json'].join('/'))
                        .done(function(data) {
                            // Afisare...
                            populateModelData(self, self.institutie(), data)
                        })
                        .fail(function() {
                            // Probleme la descarcare (curata ecran)...
                            self.cheltuieliBarTitle       (self.cheltuieliBarTitle().substring(0, self.cheltuieliBarTitle().indexOf('-')));
                            self.cheltuieliBarSeries      ([]);
                            self.cheltuieliPieTitle       ('Cheltuieli la ' + self.an() + '.12');
                            self.cheltuieliPieDataProvider(new oj.ArrayDataProvider([]));
                            self.cheltuieliTableDataSource(new oj.FlattenedTreeDataProviderView(new oj.ArrayTreeDataProvider([])));
                            self.venituriBarTitle         (self.venituriBarTitle()  .substring(0, self.venituriBarTitle().indexOf('-')));
                            self.venituriBarSeries([]);
                            self.venituriPieTitle         ('Venituri la ' + self.an() + '.12');
                            self.venituriPieDataProvider  (new oj.ArrayDataProvider([]));
                            self.venituriTableDataSource  (new oj.FlattenedTreeDataProviderView(new oj.ArrayTreeDataProvider([])));
                            self.dateTableDataProvider    (new oj.ArrayDataProvider([]));
                        })
                        .always(function() {
                            // Opreste indicatorul incarcare...
                            self.progressValue(0);
                        });
                }
            }

            /**
             * Afisare executie bugetara institutie.
             * 
             * @param self
             * @param institutiegroups
             * @param data
             */
            function populateModelData(self, institutie, executieBugetara) {
                /*
                 * Salveaza parametrii actuali in URL (bookmark)...
                 */
                schimbaParametriiInURL(self);

                // Luni (completeaza graficul cu luni goale pentru restul  anului)...
                var luni = executieBugetara.luni.slice(0);
                if (self.an() > 2016 && luni.length < 12) {
                    for (i = luni.length; i < 12; i++) {
                        luni.push(self.an() + "." + String(i + 1).padStart(2, "0"));
                    }
                }

                /*
                 * Cheltuieli (tab)
                 */

                // Cheltuieli (bar)...
                self.cheltuieliBarTitle ('Cheltuieli ' + executieBugetara.institutie.nume + ' - ' + executieBugetara.cheltuieli.total.toLocalWithCurrency());
                self.cheltuieliBarSeries($.map(executieBugetara.cheltuieli.diagrama, function(sume, desc) {
                        return { "name": desc, "items": sume };
                    })
                );
                self.cheltuieliBarGroups(luni);

                // Cheltuieli (pie)
                self.cheltuieliPieTitle       ('Cheltuieli la ' + executieBugetara.luni.last());
                self.cheltuieliPieDataProvider(new oj.ArrayDataProvider(executieBugetara.cheltuieli.tabel));

                // Cheltuieli (table)...
                self.cheltuieliTableDataSource(
                    new oj.FlattenedTreeDataProviderView(
                        new oj.ArrayTreeDataProvider(executieBugetara.cheltuieli.tabel, {
                            implicitSort      : [ { attribute: 'suma', direction: 'descending' } ],
                            childrenAttribute : 'linii'
                        })
                ));

                /*
                 * Venituri (tab)
                 */

                // Venituri (bar)...
                self.venituriBarTitle ('Venituri ' + executieBugetara.institutie.nume + ' - ' + executieBugetara.venituri.total.toLocalWithCurrency());
                self.venituriBarSeries($.map(executieBugetara.venituri.diagrama, function(sume, desc) {
                       return { "name": desc, "items": sume };
                   })
                );
                self.venituriBarGroups(luni);

                // Venituri (pie)...
                self.venituriPieTitle       ('Venituri la ' + executieBugetara.luni.last());
                self.venituriPieDataProvider(new oj.ArrayDataProvider(executieBugetara.venituri.tabel));

                // Venituri (table)...
                self.venituriTableDataSource(
                    new oj.FlattenedTreeDataProviderView(
                        new oj.ArrayTreeDataProvider(executieBugetara.venituri.tabel, {
                            implicitSort      : [ { attribute: 'suma', direction: 'descending' } ],
                            childrenAttribute : 'linii'
                        })
                ));

                /*
                 * Date (tab)
                 */

                 // Date (table)...
                 self.dateTableDataProvider(new oj.ArrayDataProvider(executieBugetara.date || [], {
                    implicitSort : [ { attribute: 'luna', direction: 'ascending' } ],
                 }));
            }

            /**
             * Afiseaza calendar evenimente aprobare bugete locale.
             * @param self
             * @param an
             */
            function populeazaDateCronologie(self, an) {
                switch (an) {
                    case 2026:
                        self.pasiCronologie([
                            { id: 'pas1', label: '27 Martie 2026 Legea bugetului de stat publicată în Monitorul Oficial'},
                            { id: 'pas2', label: '27 Martie – 11 Aprilie 2026 Publicare proiect buget local + deschidere contestații' },
                            { id: 'pas3', label: '11 Aprilie – 26 Aprilie 2026 Termen limită depunere contestații' },
                            { id: 'pas4', label: '26 Aprilie – 1 Mai 2026 Proiect înaintat Consiliului Local' },
                            { id: 'pas5', label: '1 Mai – 11 Mai 2026 Vot și adoptare buget local de către Consiliul Local' }
                        ]);
                        self.pasCronologie('pas5');
                        self.afiseazaCronologie(true);
                        break;
                    default:
                        self.pasiCronologie([
                            { id: 'pas1', label: 'Legea bugetului de stat publicată în Monitorul Oficial'},
                            { id: 'pas2', label: 'Până la 15 zile Publicare proiect buget local + deschidere contestații' },
                            { id: 'pas3', label: 'Până la 15 zile Termen limită depunere contestații' },
                            { id: 'pas4', label: 'Până la 5 zile Proiect înaintat Consiliului Local' },
                            { id: 'pas5', label: 'Până la 10 zile Vot și adoptare buget local de către Consiliul Local' }
                        ]);
                        self.pasCronologie('pas5');
                        self.afiseazaCronologie(true);
                        break;
                }
            }

            function populeazaDateFooter(self) {
                 // UATuri footer (table)...
                 const uaturiSumar = [
                    { clasificare: "Municipii (inclusiv Municipiul Bucureşti)", numar: 103 },
                    { clasificare: "Oraşe", numar: 216 },
                    { clasificare: "Comune", numar:  2.862 },
                    { clasificare: "Judeţe", numar: 41 },
                    { clasificare: "Sectoare ale Municipiului Bucureşti", numar: 6 },
                    { clasificare: "TOTAL", numar: 3.228 },
                 ];
                 self.uatTableDataProvider(new oj.ArrayDataProvider(uaturiSumar));
            }

            /*
             * Stocheaza parametrii in URL pentru bookmarking...
             */
            function schimbaParametriiInURL(self) {
                if (self.judet() && self.institutie() && self.an()) {
                   var queryParams = new URLSearchParams();
                   queryParams.set('judet',      self.judet());
                   queryParams.set('institutie', self.institutie());
                   queryParams.set('an',         self.an());
                   queryParams.set('tab',        self.tabCurent());
                   window.history.replaceState({}, '', '?' + queryParams);
                }
            }

            /*
             * ViewModel (return)
             */
            return pageViewModel;
        }
);

/*
 * Print as local RO currency
 */
Number.prototype.toLocalWithCurrency = function() {
    return this.toLocaleString('ro', { style: 'currency', currency: 'RON', minimumFractionDigits: 0, maximumFractionDigits: 0 })
};

Number.prototype.toLocalWithoutCurrency = function() {
    return this.toLocaleString('ro', { style: 'decimal', minimumFractionDigits: 0, maximumFractionDigits: 0 })
}

/*
 * Get last element from array
 */
Array.prototype.last = function() {
    return this[this.length - 1];
}
